import{_ as a,o as t,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Code Walkthroughs: BlueStore SMR","description":"","frontmatter":{"title":"Ceph Code Walkthroughs: BlueStore SMR","date":"2021-08-21T00:00:00.000Z","updated":"2021-08-21T00:00:00.000Z","tags":["Ceph","BlueStore","SMR","Distributed Storage","Code Optimization"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Code_Walkthroughs_-_BlueStore_SMR.md","filePath":"posts/2021/Ceph_Code_Walkthroughs_-_BlueStore_SMR.md","lastUpdated":1780459816000}'),r={name:"posts/2021/Ceph_Code_Walkthroughs_-_BlueStore_SMR.md"};function i(n,e,h,s,d,u){return t(),l("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph存储系统中smr-shingled-magnetic-recording-智能驱动器的代码更新与讨论" tabindex="-1">会议主题：Ceph存储系统中SMR（Shingled Magnetic Recording）智能驱动器的代码更新与讨论 <a class="header-anchor" href="#会议主题-ceph存储系统中smr-shingled-magnetic-recording-智能驱动器的代码更新与讨论" aria-label="Permalink to &quot;会议主题：Ceph存储系统中SMR（Shingled Magnetic Recording）智能驱动器的代码更新与讨论&quot;">​</a></h4><h4 id="参会人员-ceph研发团队成员" tabindex="-1">参会人员：Ceph研发团队成员 <a class="header-anchor" href="#参会人员-ceph研发团队成员" aria-label="Permalink to &quot;参会人员：Ceph研发团队成员&quot;">​</a></h4><h4 id="会议时间-待定" tabindex="-1">会议时间：待定 <a class="header-anchor" href="#会议时间-待定" aria-label="Permalink to &quot;会议时间：待定&quot;">​</a></h4><h4 id="会议地点-视频会议" tabindex="-1">会议地点：视频会议 <a class="header-anchor" href="#会议地点-视频会议" aria-label="Permalink to &quot;会议地点：视频会议&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>SMR智能驱动器的代码更新</strong>：</p><ul><li>讨论了针对HSM（Host-Managed SMR）智能驱动器的代码更新，包括内核设备的支持和SMR特定功能的添加。</li><li>介绍如何通过SMART特定调用来获取设备上的区域信息，如区域数量和传统区域数量。</li></ul></li><li><p><strong>Zoned Allocator和Zone Freelist Manager的更新</strong>：</p><ul><li>详细讨论了Zoned Allocator和Zone Freelist Manager的实现细节，包括新的清理线程的添加和设备参数的处理。</li><li>讨论了如何处理对象的区域编号和偏移量，以及如何在数据库中维护这些信息。</li></ul></li><li><p><strong>代码优化和未来工作</strong>：</p><ul><li>讨论了是否需要继续使用ZBD库以保持对旧内核的兼容性，以及是否需要紧急移除它。</li><li>讨论了如何处理多区域同时清理的问题，以及如何简化这一过程。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li><strong>ZBD库的使用</strong>：决定不紧急移除ZBD库，以保持对旧内核的兼容性。</li><li><strong>多区域清理</strong>：决定简化多区域清理过程，每次只清理一个区域，以减少复杂性和潜在的错误。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li><strong>代码审查和优化</strong>：对现有代码进行详细审查，特别是Zoned Allocator和Zone Freelist Manager的实现，确保其正确性和效率。</li><li><strong>兼容性测试</strong>：在不同内核版本上进行兼容性测试，确保代码在各种环境下都能稳定运行。</li><li><strong>文档更新</strong>：更新相关文档，包括代码注释和用户手册，以便其他开发者更好地理解和维护代码。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>会议中提到的“zone append”命令是一个新的内核命令，用于简化SMR驱动器的写操作。</li><li>会议结束时，团队成员表示将通过电子邮件跟进会议中提到的待办事项。</li></ul><h4 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h4><p>本次会议主要讨论了Ceph存储系统中SMR智能驱动器的代码更新和优化问题。团队对现有代码进行了深入的讨论，并制定了后续的行动计划，包括代码审查、兼容性测试和文档更新等，以确保SMR驱动器的支持得到优化和改进。</p>',15)])])}const g=a(r,[["render",i]]);export{p as __pageData,g as default};
